143	      var start = rows[i].querySelector(".hour-start").value;
144	      var end = rows[i].querySelector(".hour-end").value;
145	      if (!start || !end) {
146	        return { error: "第 " + (i + 1) + " 个开放时段未填写完整，请补全或删除该时段。" };
147	      }
148	      hours.push({ weekday: weekday, start: start, end: end });
149	    }
150	    return { hours: hours };
151	  }
