153	  function toMinutes(hhmm) {
154	    var parts = hhmm.split(":");
155	    return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
156	  }
157	
158	  function escapeHTML(value) {
159	    return String(value).replace(/[&<>"']/g, function (c) {
160	      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
161	    });
162	  }
163	
164	  function renderVenues(venues) {
165	    if (!venues.length) {
166	      listBox.innerHTML = '<div class="empty">还没有场地记录。</div>';
167	      return;
168	    }
169	    var sortedHours = function (hours) {
170	      return hours.slice().sort(function (a, b) {
171	        if (a.weekday !== b.weekday) return a.weekday - b.weekday;
172	        return toMinutes(a.start) - toMinutes(b.start);
173	      });
174	    };
175	    listBox.innerHTML = venues.map(function (venue) {
176	      var hoursHTML;
177	      if (!venue.weeklyHours || !venue.weeklyHours.length) {
178	        hoursHTML = '<p class="venue-meta">开放时段：暂未开放</p>';
179	      } else {
180	        var items = sortedHours(venue.weeklyHours).map(function (h) {
181	          var overnight = toMinutes(h.end) < toMinutes(h.start);
182	          var endLabel = overnight ? '<span class="next-day">次日 ' + escapeHTML(h.end) + "</span>" : escapeHTML(h.end);
183	          return "<li>" + WEEKDAYS[h.weekday] + " " + escapeHTML(h.start) + " – " + endLabel + "</li>";
184	        }).join("");
185	        hoursHTML = '<ul class="hours">' + items + "</ul>";
186	      }
187	      return '<article class="venue-card">' +
188	        "<h3>" + escapeHTML(venue.name) + "</h3>" +
189	        '<p class="venue-meta">容量：' + venue.capacity + " 人</p>" +
190	        '<p class="venue-meta">时区：' + escapeHTML(venue.timezone) + "</p>" +
191	        hoursHTML +
192	        "</article>";
193	    }).join("");
194	  }
195	
196	  function loadVenues() {
197	    return fetch("/api/venues", { headers: { Accept: "application/json" } })
198	      .then(function (res) {
199	        if (!res.ok) throw new Error("读取场地列表失败（HTTP " + res.status + "）");
200	        return res.json();
201	      })
202	      .then(function (data) { renderVenues(data.venues || []); })
203	      .catch(function (err) {
204	        listBox.innerHTML = '<div class="empty">' + escapeHTML(err.message) + "</div>";
205	      });
206	  }
