208	  form.addEventListener("submit", function (event) {
209	    event.preventDefault();
210	    clearError();
211	
212	    var name = document.getElementById("name").value.trim();
213	    var capacityRaw = document.getElementById("capacity").value;
214	    var timezone = document.getElementById("timezone").value.trim();
215	    var capacity = parseInt(capacityRaw, 10);
216	
217	    if (!name) { showError("保存失败：名称不能为空。"); return; }
218	    if (!/^\d+$/.test(capacityRaw) || capacity <= 0) { showError("保存失败：容量必须是正整数。"); return; }
219	    if (!timezone) { showError("保存失败：请填写所在时区。"); return; }
220	
221	    var collected = collectHours();
222	    if (collected.error) { showError("保存失败：" + collected.error); return; }
223	
224	    // 失败时不重置表单，保留全部填写内容。
225	    fetch("/api/venues", {
226	      method: "POST",
227	      headers: { "Content-Type": "application/json", Accept: "application/json" },
228	      body: JSON.stringify({
229	        name: name,
230	        capacity: capacity,
231	        timezone: timezone,
232	        weeklyHours: collected.hours
233	      })
234	    }).then(function (res) {
235	      return res.json().catch(function () { return {}; }).then(function (body) {
236	        return { ok: res.ok, status: res.status, body: body };
237	      });
238	    }).then(function (result) {
239	      if (!result.ok) {
240	        var reason = result.body && result.body.error ? result.body.error : "HTTP " + result.status;
241	        showError("保存失败：" + reason);
242	        return;
243	      }
244	      form.reset();
245	      hoursRows.innerHTML = "";
246	      clearError();
247	      return loadVenues();
248	    }).catch(function (err) {
249	      showError("保存失败：无法连接服务（" + err.message + "），请稍后重试。");
250	    });
251	  });
252	
253	  loadVenues();
254	})();
