203		t.Helper()
204		var out map[string]any
205		if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
206			t.Fatalf("response is not JSON object: %q (%v)", rec.Body.String(), err)
207		}
208		return out
209	}
