// capacityText 返回某条场地容量的逐位准确十进制文本。优先使用从原始 JSON
// 文本中提取的数字字面量；只有提取缺失时才回退到解析值，绝不主动舍入。
function capacityText(venue) {
  if (Object.prototype.hasOwnProperty.call(venue, "capacityText")) {
    return venue.capacityText;
  }
  return String(venue.capacity);
}

// parseVenuesJSON 在不经过 Number 的情况下读取场地列表。直接 JSON.parse 会把
// 9007199254740993 这样超过 2^53 的数字舍成相邻整数，因此先在原始文本里按
// JSON 数字词法逐位捕获每个场地的 capacity，再解析其余字段，最后把准确的
// 十进制文本挂回每条记录，保证输入、提交和列表指向同一个整数。
function parseVenuesJSON(text) {
  var data = JSON.parse(text);
  var venues = data.venues || [];
  var tokens = [];
  var numberPattern = /"capacity"[ \t\n\r]*:[ \t\n\r]*(-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)/g;
  var match;
  while ((match = numberPattern.exec(text)) !== null) {
    tokens.push(match[1]);
  }
  // 正常响应里一个场地恰好对应一个 capacity，顺序与数组一致；只有数量对得上
  // 时才采用提取值，避免错配到错误的记录。
  if (tokens.length === venues.length) {
    for (var i = 0; i < venues.length; i++) {
      venues[i].capacityText = tokens[i];
    }
  }
  return venues;
}

