let requestBody = JSON.stringify({ name: "音乐厅", timezone: "Asia/Shanghai", weeklyHours: [] });
requestBody = requestBody.replace(/^\{/, '{"capacity":' + capacityDigits + ",");
const reparsed = JSON.parse(requestBody);
