file.content:
    // 去掉前导零（如 000120 -> 120），保持原有取值的同时保证它是合法 JSON
    // 数字（JSON 不允许多余前导零）；去掉前导零后只剩 "0" 说明填的是零。
    var capacityDigits = capacityRaw.replace(/^0+(?=\d)/, "");
    if (capacityDigits === "0") { showError("保存失败：容量必须是正整数。"); return; }
    if (!timezone) { showError("保存失败：请填写所在时区。"); return; }

    var collected = collectHours();
    if (collected.error) { showError("保存失败：" + collected.error); return; }

    // capacity 仍是 JSON 数字：把逐位准确的十进制文本直接拼进请求体，绝不经过
    // Number/parseInt，避免超过 2^53 的整数在提交前被改成相邻整数。
    var requestBody = JSON.stringify({
      name: name,
      timezone: timezone,
      weeklyHours: collected.hours
    });
    requestBody = requestBody.replace(/^\{/, '{"capacity":' + capacityDigits + ",");

    // 失败时不重置表单，保留全部填写内容。
    fetch("/api/venues", {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: requestBody
    }).then(function (res) {
      return res.json().catch(function () { return {}; }).then(function (body) {
        return { ok: res.ok, status: res.status, body: body };
      });
    }).then(function (result) {
      if (!result.ok) {
        var reason = result.body && result.body.error ? result.body.error : "HTTP " + result.status;
        showError("保存失败：" + reason);
        return;
      }
      form.reset();
      hoursRows.innerHTML = "";
      clearError();
      return loadVenues();
    }).catch(function (err) {
      showError("保存失败：无法连接服务（" + err.message + "），请稍后重试。");
    });
  });

  loadVenues();
})();
</script>
